from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from .models import Invoice

MANAGER_LIMIT = Decimal("50000.00")
DIRECTOR_LIMIT = Decimal("500000.00")


@dataclass(frozen=True)
class ApprovalDecision:
    allowed: bool
    reason: str | None = None


def _format_amount(value: Decimal) -> str:
    return f"{value:,.2f}"


def _role_for_approver(approver: str) -> str:
    mapping = {
        "demo.manager": "Manager",
        "demo.director": "Director",
        "demo.director2": "Director",
        "demo.admin": "Admin",
    }
    return mapping.get(approver, "Unknown")


def evaluate_approval(invoice: Invoice, approver: str) -> ApprovalDecision:
    role = _role_for_approver(approver)

    if role == "Admin":
        return ApprovalDecision(False, "Role Admin cannot approve invoices.")

    if role not in {"Manager", "Director"}:
        return ApprovalDecision(False, f"Role {role} cannot approve invoices.")

    if role == "Manager" and invoice.amount > MANAGER_LIMIT:
        return ApprovalDecision(
            False,
            f"Invoice amount {_format_amount(invoice.amount)} exceeds the Manager approval limit of {_format_amount(MANAGER_LIMIT)}.",
        )

    if role == "Director" and invoice.amount > DIRECTOR_LIMIT:
        return ApprovalDecision(
            False,
            f"Invoice amount {_format_amount(invoice.amount)} exceeds the Director approval limit of {_format_amount(DIRECTOR_LIMIT)}.",
        )

    return ApprovalDecision(True)

